"""What a mirror's generated files say, and a guide's links made to work from it."""

from __future__ import annotations

import posixpath
import re

PICTURES = (".webp", ".png", ".jpg", ".gif", ".svg")
# A link's target: inline, a picture's src, or a reference's definition.
LINK = re.compile(r'(\]\(|src="|^\[[^\]]+\]: )([^)\s"]+)', re.M)

